export function sceneSVG(p,time,ids,transparent=false,renderContext={}){const prune=n=>ids.includes(n.id)?n:{...n,children:(n.children||[]).map(prune).filter(Boolean),type:'group'};const keep=n=>ids.includes(n.id)||n.children?.some(keep);const exportable=list=>list.filter(n=>!n.reference||n.exportIncluded).map(n=>n.type==='group'?{...n,children:exportable(n.children)}:n);const nodes=ids?p.layers.filter(keep).map(prune):exportable(p.layers);return `<svg xmlns="${NS}" width="${p.width}" height="${p.height}" viewBox="0 0 ${p.width} ${p.height}">${transparent?'':`<rect width="100%" height="100%" fill="${escape(p.background)}"/>`}${nodes.map(n=>artwork(n,time,false,false,undefined,{fps:p.fps,duration:p.duration,meshResolution:2048,meshPixelScale:1,...renderContext})).join('')}</svg>`;}
